try {
const headersIn = $json.headers ?? {};
const body = $json.body ?? $json;
const query = $json.query ?? {};
const githubEvent = String(headersIn['x-github-event'] ?? headersIn['X-GitHub-Event'] ?? '').toLowerCase();
const githubAction = body.action ?? null;
const pullRequest = body.pull_request ?? null;
const isGithubPullRequestEvent = githubEvent === 'pull_request' || Boolean(pullRequest);
const reviewMode = body.reviewMode ?? (isGithubPullRequestEvent ? 'quick' : 'standard');
const provider = body.provider ?? $evaluateExpression('{{ $env.LLM_PROVIDER }}') ?? 'openrouter';
const model = body.model ?? (provider === 'openrouter' ? ($evaluateExpression('{{ $env.OPENROUTER_MODEL }}') ?? 'openai/gpt-oss-20b:free') : ($evaluateExpression('{{ $env.OPENAI_MODEL }}') ?? 'gpt-5.4-nano'));
const apiKey = provider === 'openrouter' ? $evaluateExpression('{{ $env.OPENROUTER_API_KEY }}') : $evaluateExpression('{{ $env.OPENAI_API_KEY }}');
const apiUrl = provider === 'openrouter' ? 'https://openrouter.ai/api/v1/chat/completions' : 'https://api.openai.com/v1/chat/completions';
const gitToken = $evaluateExpression('{{ $env.GIT_TOKEN }}');
const webhookToken = $evaluateExpression('{{ $env.WEBHOOK_TOKEN }}');
const requestToken = query.token ?? headersIn['x-speedsters-token'] ?? headersIn['X-Speedsters-Token'] ?? null;

if (webhookToken && requestToken !== webhookToken) {
  return [{ json: { ok: false, skipped: true, reason: 'Invalid webhook token' } }];
}

if (githubEvent === 'ping') {
  return [{ json: { ok: true, skipped: true, reason: 'GitHub webhook ping received' } }];
}

if (isGithubPullRequestEvent) {
  const allowedActions = ['opened', 'reopened', 'synchronize', 'ready_for_review'];
  if (githubAction && !allowedActions.includes(githubAction)) {
    return [{ json: { ok: true, skipped: true, trigger: 'github_pull_request', githubAction, reason: 'Pull request action is not configured for neuroreview' } }];
  }
}

if (!apiKey || apiKey === 'sk-replace-me' || apiKey === 'sk-or-replace-me') {
  return [{ json: { ok: false, error: (provider === 'openrouter' ? 'OPENROUTER_API_KEY' : 'OPENAI_API_KEY') + ' is not configured in the n8n environment' } }];
}

const repository = body.repository?.full_name ?? body.repository ?? 'unknown';
const pullRequestUrl = body.pullRequestUrl ?? pullRequest?.html_url ?? null;
const pullRequestCommentsUrl = body.pullRequestCommentsUrl ?? pullRequest?.comments_url ?? null;
let diff = body.diff ?? body.patch ?? null;
let diffSource = body.diff ? 'inline diff' : body.patch ? 'inline patch' : null;

function normalizeGithubDiffUrl(url) {
  const cleanUrl = String(url).replace(/[#?].*$/, '').replace(/\/$/, '');
  if (cleanUrl.endsWith('.diff')) return cleanUrl;
  if (/github\.com\/.+\/pull\/\d+$/i.test(cleanUrl)) return cleanUrl + '.diff';
  return null;
}

if (!diff) {
  const diffUrl = body.diffUrl ?? pullRequest?.diff_url ?? (pullRequestUrl ? normalizeGithubDiffUrl(pullRequestUrl) : null);
  if (diffUrl) {
    const diffHeaders = { Accept: 'application/vnd.github.v3.diff' };
    if (gitToken) diffHeaders.Authorization = 'Bearer ' + gitToken;
    let diffResponse;
    try {
      diffResponse = await this.helpers.httpRequest({ method: 'GET', url: diffUrl, headers: diffHeaders, timeout: 10000 });
    } catch (error) {
      return [{ json: { ok: false, error: 'Failed to fetch PR diff: ' + (error.message ?? String(error)) } }];
    }
    diff = typeof diffResponse === 'string' ? diffResponse : JSON.stringify(diffResponse);
    diffSource = diffUrl;
  }
}

if (!diff || !String(diff).trim()) {
  return [{ json: { ok: false, error: 'Request must include diff, patch, pullRequestUrl, diffUrl, or GitHub pull_request webhook payload' } }];
}

const maxChunkSize = reviewMode === 'quick' ? 6000 : reviewMode === 'strict' ? 9000 : 8000;
const requestedMaxFindings = Number(body.maxFindings ?? (reviewMode === 'strict' ? 5 : reviewMode === 'quick' ? 1 : 3));
const cappedMaxFindings = Math.min(Math.max(Number.isFinite(requestedMaxFindings) ? requestedMaxFindings : 3, 1), 5);

function normalizeDiffPath(path) {
  return String(path ?? '').replace(/^([ab])\//, '').replace(/:\d+$/, '');
}

function isNoisePath(path) {
  const normalized = normalizeDiffPath(path);
  return /(^|\/)(package-lock\.json|yarn\.lock|pnpm-lock\.yaml)$/.test(normalized)
    || /(^|\/)(dist|build|coverage)\//.test(normalized)
    || normalized === 'README.md'
    || normalized === '.gitignore'
    || normalized.startsWith('docs/')
    || normalized === 'n8n/.env.example'
    || normalized === 'n8n/docker-compose.yml'
    || normalized === 'n8n/import-local-workflow.sh';
}

function extractChunkPath(chunk) {
  const match = String(chunk).match(/^diff --git a\/(.*?) b\/(.*)$/m);
  return match ? normalizeDiffPath(match[2]) : null;
}

const changedFiles = new Set([...String(diff).matchAll(/^diff --git a\/(.*?) b\/(.*)$/gm)].map((match) => normalizeDiffPath(match[2])));
const fileChunks = String(diff)
  .split('\ndiff --git ')
  .map((part, index) => (index === 0 ? part : 'diff --git ' + part))
  .filter((chunk) => chunk.trim().length > 0)
  .filter((chunk) => {
    const path = extractChunkPath(chunk);
    return !path || !isNoisePath(path);
  });

const chunks = [];
const selectedFileChunks = isGithubPullRequestEvent ? fileChunks.slice(0, 2) : fileChunks;
const reviewInputs = isGithubPullRequestEvent ? selectedFileChunks : (selectedFileChunks.length ? selectedFileChunks : [String(diff)]);
for (const fileChunk of reviewInputs) {
  const reviewText = isGithubPullRequestEvent ? fileChunk.slice(0, 1200) : fileChunk;
  for (let start = 0; start < reviewText.length; start += maxChunkSize) {
    chunks.push(reviewText.slice(start, start + maxChunkSize));
  }
}

const systemPrompt = [
  'Ты старший инженер на code review. Все поля ответа строго на русском языке.',
  'Будь предельно избирателен: ищи только дефекты, которые с высокой вероятностью сломают выполнение, безопасность, совместимость API, миграции или обработку ошибок.',
  'Запрещено комментировать стиль, документацию, локальный запуск, docker-compose, shell-скрипты, .env.example, hardening без немедленного риска, пожелания и общие best practices.',
  'Верни не больше ' + cappedMaxFindings + ' самых важных замечаний. В режиме quick верни 0 или 1 замечание. Если сомневаешься, не пиши замечание.',
  'Не придумывай файлы, строки и поведение. Файл должен существовать в diff. Не дроби один риск на несколько замечаний.',
  'Ответь только JSON без markdown fences. Формат: массив объектов. Каждый элемент: severity, file, line, title, description, recommendation.',
  'severity: critical, high, medium или low. Если реальных замечаний нет, верни [].'
].join(' ');

async function reviewChunk(chunk, index) {
  const data = await this.helpers.httpRequest({
    method: 'POST',
    url: apiUrl,
    headers: {
      Authorization: 'Bearer ' + apiKey,
      'Content-Type': 'application/json',
      'HTTP-Referer': 'http://localhost:5678',
      'X-Title': 'Speedsters Neuroreview'
    },
    body: {
      model,
      temperature: 0.1,
      messages: [
        { role: 'system', content: systemPrompt },
        {
          role: 'user',
          content: 'Repository: ' + repository + '\nPull request: ' + (pullRequestUrl ?? 'not provided') + '\nReview mode: ' + reviewMode + '\nMax findings: ' + cappedMaxFindings + '\nChunk: ' + (index + 1) + '/' + chunks.length + '\n\nВерни только JSON-массив на русском языке, без markdown и пояснительного текста. Не больше ' + cappedMaxFindings + ' самых важных замечаний.\n\nDiff:\n' + chunk
        }
      ]
    },
    json: true,
    timeout: 12000
  });
  const rawContent = data.choices?.[0]?.message?.content ?? '{"findings":[]}';
  const fence = String.fromCharCode(96).repeat(3);
  let content = String(rawContent).trim();
  if (content.toLowerCase().startsWith(fence + 'json')) content = content.slice((fence + 'json').length).trim();
  else if (content.startsWith(fence)) content = content.slice(fence.length).trim();
  if (content.endsWith(fence)) content = content.slice(0, -fence.length).trim();
  try {
    const parsed = JSON.parse(content);
    if (Array.isArray(parsed)) return parsed;
    if (Array.isArray(parsed.findings)) return parsed.findings;
    return [];
  } catch (error) {
    return [{
      severity: 'low',
      file: null,
      line: null,
      title: 'LLM response parse failed',
      description: content.slice(0, 1000),
      recommendation: 'Уточнить prompt или проверить ответ модели вручную.'
    }];
  }
}

const allFindings = [];
for (let index = 0; index < chunks.length; index += 1) {
  allFindings.push(...await reviewChunk(chunks[index], index));
}

const rank = { critical: 0, high: 1, medium: 2, low: 3 };
const unique = new Map();
for (const finding of allFindings) {
  const severity = ['critical', 'high', 'medium', 'low'].includes(finding.severity) ? finding.severity : 'medium';
  const findingFile = normalizeDiffPath(finding.file);
  if (findingFile && changedFiles.size > 0 && !changedFiles.has(findingFile)) continue;
  if (findingFile && isNoisePath(findingFile)) continue;
  const normalized = {
    severity,
    file: findingFile || null,
    line: finding.line ?? null,
    title: finding.title ?? 'Untitled finding',
    description: finding.description ?? '',
    recommendation: finding.recommendation ?? ''
  };
  const key = normalized.severity + '|' + normalized.file + '|' + normalized.line + '|' + normalized.title;
  if (!unique.has(key)) unique.set(key, normalized);
}

const sortedFindings = [...unique.values()].sort((a, b) => (rank[a.severity] ?? 9) - (rank[b.severity] ?? 9));
const nonLowFindings = sortedFindings.filter((item) => item.severity !== 'low');
const findingsPool = nonLowFindings.length > 0 ? nonLowFindings : sortedFindings;
const findings = findingsPool.slice(0, cappedMaxFindings);
const suppressedFindings = Math.max(sortedFindings.length - findings.length, 0);
const summary = findings.length === 0
  ? 'Замечаний уровня code review не найдено.'
  : 'Найдено замечаний: ' + findings.length + '. Critical: ' + findings.filter((item) => item.severity === 'critical').length + ', high: ' + findings.filter((item) => item.severity === 'high').length + ', medium: ' + findings.filter((item) => item.severity === 'medium').length + ', low: ' + findings.filter((item) => item.severity === 'low').length + (suppressedFindings > 0 ? '. Скрыто менее важных замечаний: ' + suppressedFindings + '.' : '.');
const tick = String.fromCharCode(96);
const markdown = [
  '# Neuroreview: ' + repository,
  '',
  pullRequestUrl ? 'PR: ' + pullRequestUrl : null,
  pullRequest?.title ? 'Title: ' + pullRequest.title : null,
  summary,
  '',
  ...findings.map((finding) => [
    '## ' + finding.severity.toUpperCase() + ': ' + finding.title,
    '',
    finding.file ? 'Файл: ' + tick + finding.file + (finding.line ? ':' + finding.line : '') + tick : 'Файл: не указан',
    '',
    finding.description,
    '',
    'Рекомендация: ' + finding.recommendation
  ].join('\n'))
].filter((line) => line !== null).join('\n');

let commentPosted = false;
let commentError = null;
if (isGithubPullRequestEvent && pullRequestCommentsUrl && gitToken && body.postComment !== false) {
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: pullRequestCommentsUrl,
      headers: {
        Authorization: 'Bearer ' + gitToken,
        Accept: 'application/vnd.github+json',
        'Content-Type': 'application/json'
      },
      body: { body: markdown },
      json: true,
      timeout: 10000
    });
    commentPosted = true;
  } catch (error) {
    commentError = error.message ?? String(error);
  }
}

return [{
  json: {
    ok: true,
    trigger: isGithubPullRequestEvent ? 'github_pull_request' : 'manual',
    githubAction,
    repository,
    pullRequestUrl,
    diffSource,
    reviewMode,
    provider,
    model,
    chunksReviewed: chunks.length,
    summary,
    findings,
    suppressedFindings,
    markdown,
    commentPosted,
    commentError
  }
}];
} catch (error) {
  return [{ json: { ok: false, error: error.message ?? String(error) } }];
}
